import { GoogleGenAI, Type } from "@google/genai";
import { DetectedElement, LayerType } from "../types";

// Schema for the Gemini response
const segmentationSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      label: {
        type: Type.STRING,
        description: "A short descriptive name for the object or layer (e.g., 'Red Car', 'Header Text', 'Background').",
      },
      category: {
        type: Type.STRING,
        enum: [LayerType.OBJECT, LayerType.TEXT, LayerType.BACKGROUND, LayerType.COMPOSITION],
        description: "The type of layer. Use 'composition' for the entry describing the entire image style.",
      },
      box_2d: {
        type: Type.ARRAY,
        items: { type: Type.INTEGER },
        description: "Bounding box in the format [ymin, xmin, ymax, xmax] on a 0-1000 scale.",
      },
      visual_prompt: {
        type: Type.STRING,
        description: "A structured prompt. For 'composition', use headers: Theme, Headline & Text, Visuals, Layout/Sections, Footer, Style. For objects, use: Object, Visual Details, Style.",
      }
    },
    required: ["label", "category", "box_2d", "visual_prompt"],
  },
};

export const analyzeImageStructure = async (
  base64Image: string,
  mimeType: string
): Promise<DetectedElement[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      Analyze this image for a design decomposition tool. 
      Identify distinct visual elements that a designer would want on separate layers.

      Rules:
      1. Always identify the main "Background" or scene setting.
      2. Identify primary foreground objects (people, products, vehicles).
      3. Identify distinct text blocks (headlines, body copy).
      4. INCLUDE a "composition" element that covers the entire image ([0, 0, 1000, 1000]).
      5. Be precise with bounding boxes (0-1000 scale).
      6. Do not overlap boxes excessively unless objects are truly nested.

      CRITICAL - PROMPT STRUCTURE:
      7. For the 'composition' element, the 'visual_prompt' MUST follow this exact structure:
         Create a [Type of Design, e.g. Flyer, Poster].
         Theme: [Description of mood/theme].
         Headline & Text: [Details of main titles, subtext, taglines, font styles].
         Visuals: [Detailed description of models, objects, props, effects, lighting].
         Layout/Sections: [Description of specific sections like Services, lists].
         Footer: [Details of footer area, contact info].
         Style: [Art style, colors, resolution, finishing].

      8. For individual elements (objects/layers), use a similar structured format focused on that object:
         Object: [Name/Type]
         Visuals: [Detailed texture, lighting, angle, material, colors]
         Style: [Matches the main composition style]

      9. Return a list of these elements in JSON format.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: prompt,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: segmentationSchema,
        temperature: 0.2,
      },
    });

    let text = response.text;
    if (!text) {
      throw new Error("No response from AI");
    }

    // Clean markdown if present
    if (text.trim().startsWith("```")) {
      text = text.replace(/^```(json)?\s*/, "").replace(/\s*```$/, "");
    }

    const data = JSON.parse(text) as DetectedElement[];
    return data;
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

export const generateElementImage = async (prompt: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Use gemini-2.5-flash-image for generation
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: prompt,
          },
        ],
      },
      config: {
        // No responseMimeType for image models
      }
    });

    // Iterate to find image part
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image data found in response");
  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

export const regeneratePrompt = async (currentPrompt: string, layerType: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `You are a creative design assistant. Given the following visual prompt for an image layer of type '${layerType}', generate a NEW, CREATIVE variation that maintains the same core concept but uses different adjectives, styles, lighting, or artistic details. Keep it concise.

Current Prompt: ${currentPrompt}

New Variation:`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text?.trim() || currentPrompt;
  } catch (error) {
    console.error("Gemini Regenerate Prompt Error:", error);
    return currentPrompt;
  }
};

import React, { useState, useEffect } from 'react';
import { UploadZone } from './components/UploadZone';
import { LandingPage } from './components/LandingPage';
import { LayerList } from './components/LayerList';
import { CanvasEditor } from './components/CanvasEditor';
import { AppState, ImageMetadata, Layer, DetectedElement, LayerType } from './types';
import { analyzeImageStructure, generateElementImage, regeneratePrompt } from './services/geminiService';
import { Button } from './components/Button';
// @ts-ignore
import JSZip from 'jszip';

// Utility to crop image based on coordinates
const cropImage = async (
  sourceImage: HTMLImageElement, 
  box_1000: number[]
): Promise<{ url: string; x: number; y: number; w: number; h: number }> => {
  const [ymin, xmin, ymax, xmax] = box_1000;
  const canvas = document.createElement('canvas');

  // Calculate pixel coordinates
  const x = (xmin / 1000) * sourceImage.naturalWidth;
  const y = (ymin / 1000) * sourceImage.naturalHeight;
  const w = ((xmax - xmin) / 1000) * sourceImage.naturalWidth;
  const h = ((ymax - ymin) / 1000) * sourceImage.naturalHeight;

  // Handle invalid or empty boxes
  if (w <= 0 || h <= 0) {
    canvas.width = 1;
    canvas.height = 1;
    return {
      url: canvas.toDataURL('image/png'),
      x, y, w: 0, h: 0
    };
  }

  canvas.width = w;
  canvas.height = h;

  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error("No context");

  ctx.drawImage(
    sourceImage,
    x, y, w, h, // source rect
    0, 0, w, h // dest rect
  );

  return {
    url: canvas.toDataURL('image/png'),
    x, y, w, h
  };
};

export default function App() {
  const [state, setState] = useState<AppState>(AppState.LANDING);
  const [imageMetadata, setImageMetadata] = useState<ImageMetadata | null>(null);
  const [layers, setLayers] = useState<Layer[]>([]);
  const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isZipping, setIsZipping] = useState(false);
  const [showLayerPanel, setShowLayerPanel] = useState(true);
  const [activeTab, setActiveTab] = useState<'layers' | 'generated'>('layers');
  const [isShuffling, setIsShuffling] = useState<string | null>(null);

  // Helper to trigger download
  const downloadLayer = (layer: Layer) => {
    const link = document.createElement('a');
    link.href = layer.imageSrc;
    link.download = `${layer.name.replace(/\s+/g, '_')}_${layer.isGenerated ? 'generated' : 'layer'}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleUpdatePrompt = (layerId: string, newPrompt: string) => {
    setLayers(prev => prev.map(l => l.id === layerId ? { ...l, visual_prompt: newPrompt } : l));
  };

  const handleShufflePrompt = async (layerId: string) => {
    const layer = layers.find(l => l.id === layerId);
    if (!layer || !layer.visual_prompt) return;

    setIsShuffling(layerId);
    try {
      const newPrompt = await regeneratePrompt(layer.visual_prompt, layer.type);
      handleUpdatePrompt(layerId, newPrompt);
    } catch (err) {
      console.error(err);
    } finally {
      setIsShuffling(null);
    }
  };

  const handleLayerMove = (id: string, x: number, y: number) => {
    setLayers(prev => prev.map(l => l.id === id ? { ...l, originalX: x, originalY: y } : l));
  };

  const handleExportZip = async () => {
    const visibleLayers = layers.filter(l => l.isVisible && l.type !== LayerType.COMPOSITION);
    if (visibleLayers.length === 0) return;

    setIsZipping(true);
    try {
      const zip = new JSZip();

      visibleLayers.forEach((layer, index) => {
        const base64Data = layer.imageSrc.split(',')[1];
        const prefix = layer.isGenerated ? 'generated_' : '';
        const safeName = layer.name.replace(/[^a-z0-9]/gi, '_').toLowerCase() || `layer_${index}`;
        zip.file(`${prefix}${safeName}_${index}.png`, base64Data, { base64: true });
      });

      const blob = await zip.generateAsync({ type: 'blob' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = 'unflatten_layers.zip';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (e) {
      console.error(e);
      alert("Failed to generate ZIP file. Please try again.");
    } finally {
      setIsZipping(false);
    }
  };

  const handleGenerateLayer = async (layerId: string, prompt: string) => {
    setLayers(prev => prev.map(l => l.id === layerId ? { ...l, isGenerating: true } : l));

    try {
      const newImageSrc = await generateElementImage(prompt);
      const sourceLayer = layers.find(l => l.id === layerId);

      if (!sourceLayer) throw new Error("Source layer not found");

      const newLayerId = `gen-${layerId.substring(0, 8)}-${Date.now()}`;

      const newLayer: Layer = {
        ...sourceLayer,
        id: newLayerId,
        name: `Generated ${sourceLayer.name}`,
        type: LayerType.GENERATED,
        imageSrc: newImageSrc,
        isVisible: true,
        isGenerating: false,
        isGenerated: true,
        parentId: layerId,
        visual_prompt: prompt 
      };

      setLayers(prev => {
        const updated = prev.map(l => l.id === layerId ? { ...l, isGenerating: false } : l);
        return [...updated, newLayer];
      });

      setActiveTab('generated');
      setSelectedLayerId(newLayerId);

    } catch (err) {
      console.error("Failed to generate element:", err);
      alert("Failed to generate image. Please try again.");
      setLayers(prev => prev.map(l => l.id === layerId ? { ...l, isGenerating: false } : l));
    }
  };

  const handleFileSelect = async (file: File) => {
    setState(AppState.ANALYZING);
    setErrorMsg(null);
    setLayers([]);
    setActiveTab('layers');

    const reader = new FileReader();

    reader.onerror = () => {
      setErrorMsg("Failed to read the file. Please try again.");
      setState(AppState.ERROR);
    };

    reader.onload = async (e) => {
      const src = e.target?.result as string;
      if (!src) {
        setErrorMsg("File result is empty.");
        setState(AppState.ERROR);
        return;
      }

      const img = new Image();

      img.onerror = () => {
        setErrorMsg("Failed to load image. The file might be corrupted or unsupported.");
        setState(AppState.ERROR);
      };

      img.onload = async () => {
        setImageMetadata({
          width: img.naturalWidth,
          height: img.naturalHeight,
          src,
          file
        });

        const base64Data = src.split(',')[1];
        const mimeType = file.type;

        try {
          const detectedElements = await analyzeImageStructure(base64Data, mimeType);

          if (!detectedElements || detectedElements.length === 0) {
            throw new Error("No elements detected in the image.");
          }

          const processedLayers: Layer[] = [];
          let hasComposition = false;

          for (let i = 0; i < detectedElements.length; i++) {
            const element = detectedElements[i];
            if (!element.box_2d || element.box_2d.length !== 4) continue;

            const cropped = await cropImage(img, element.box_2d);
            if (cropped.w <= 0 || cropped.h <= 0) continue;

            if (element.category === LayerType.COMPOSITION) {
              hasComposition = true;
            }

            processedLayers.push({
              id: `layer-${i}-${Date.now()}`,
              name: element.label,
              type: element.category,
              isVisible: element.category !== LayerType.COMPOSITION,
              box: {
                ymin: element.box_2d[0],
                xmin: element.box_2d[1],
                ymax: element.box_2d[2],
                xmax: element.box_2d[3],
              },
              imageSrc: cropped.url,
              originalX: cropped.x,
              originalY: cropped.y,
              width: cropped.w,
              height: cropped.h,
              visual_prompt: element.visual_prompt || `A high quality image of ${element.label}`
            });
          }

          if (!hasComposition) {
             processedLayers.unshift({
              id: `layer-comp-${Date.now()}`,
              name: "Full Composition",
              type: LayerType.COMPOSITION,
              isVisible: false,
              box: { ymin: 0, xmin: 0, ymax: 1000, xmax: 1000 },
              imageSrc: src,
              originalX: 0,
              originalY: 0,
              width: img.naturalWidth,
              height: img.naturalHeight,
              visual_prompt: "A detailed description of this entire image composition, art style, and layout."
             });
          }

          if (processedLayers.length === 0) {
            throw new Error("Could not extract any valid layers.");
          }

          setLayers(processedLayers);
          setState(AppState.EDITING);
        } catch (err: any) {
          console.error(err);
          setErrorMsg(err.message || "Failed to analyze image. Please try again.");
          setState(AppState.ERROR);
        }
      };
      img.src = src;
    };

    reader.readAsDataURL(file);
  };

  const handleBack = () => {
    setState(AppState.LANDING);
    setLayers([]);
    setImageMetadata(null);
  };

  return (
    <div className="h-screen w-screen bg-dark-950 flex flex-col font-sans text-gray-100 overflow-hidden">

      {/* Header */}
      <header className="h-14 border-b border-dark-800 bg-dark-900 flex items-center justify-between px-4 z-10 shrink-0">
        <div className="flex items-center space-x-2 cursor-pointer" onClick={handleBack}>
          <div className="w-6 h-6 bg-gradient-to-br from-brand-500 to-indigo-600 rounded flex items-center justify-center">
            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
            </svg>
          </div>
          <span className="font-bold text-lg tracking-tight">Unflatten<span className="text-brand-500">AI</span></span>
        </div>

        {state === AppState.EDITING && (
           <div className="flex items-center space-x-2">
             <Button variant="ghost" size="sm" onClick={handleBack}>
               New
             </Button>

             <Button 
               variant="secondary" 
               size="sm" 
               onClick={() => setShowLayerPanel(!showLayerPanel)}
               className={showLayerPanel ? 'bg-dark-700' : ''}
               title={showLayerPanel ? "Hide Layers" : "Show Layers"}
             >
               <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
               </svg>
             </Button>

             <div className="w-px h-6 bg-dark-800 mx-2"></div>

             <Button 
               variant="primary" 
               size="sm" 
               disabled={isZipping}
               icon={
                 isZipping ? (
                   <svg className="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24">
                     <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                     <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                   </svg>
                 ) : (
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                  </svg>
                 )
               }
               onClick={handleExportZip}
             >
               {isZipping ? "Zipping..." : "Download ZIP"}
             </Button>
           </div>
        )}
      </header>

      {/* Main Content Area */}
      <main className="flex-1 relative flex overflow-hidden">

        {state === AppState.LANDING && (
          <LandingPage onFileSelect={handleFileSelect} />
        )}

        {state === AppState.ANALYZING && (
          <div className="w-full h-full flex flex-col items-center justify-center space-y-6 bg-dark-900">
             <div className="relative w-24 h-24">
               <div className="absolute inset-0 border-4 border-dark-700 rounded-full"></div>
               <div className="absolute inset-0 border-4 border-brand-500 rounded-full border-t-transparent animate-spin"></div>
               <div className="absolute inset-0 flex items-center justify-center">
                 <svg className="w-8 h-8 text-brand-500 animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                 </svg>
               </div>
             </div>
             <div className="text-center">
               <h3 className="text-xl font-medium text-white mb-2">Deconstructing Image</h3>
               <p className="text-gray-400">Gemini 2.5 is analyzing structure, objects, and text...</p>
             </div>
          </div>
        )}

        {state === AppState.ERROR && (
          <div className="w-full h-full flex flex-col items-center justify-center space-y-4">
             <div className="w-16 h-16 bg-red-900/20 rounded-full flex items-center justify-center">
                <svg className="w-8 h-8 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
             </div>
             <p className="text-red-400 max-w-md text-center">{errorMsg || "An unexpected error occurred."}</p>
             <div className="flex space-x-3">
               <Button onClick={handleBack} variant="secondary">Go Back</Button>
             </div>
          </div>
        )}

        {state === AppState.EDITING && imageMetadata && (
          <>
            <div className="w-14 bg-dark-900 border-r border-dark-800 flex flex-col items-center py-4 space-y-4 z-20 shrink-0">
               <div className="p-2 bg-brand-900/30 text-brand-500 rounded cursor-pointer" title="Selection Tool">
                 <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 15l-2 5L9 9l11 4-5 2zm0 0l5 5M7.188 2.239l.777 2.897M5.136 7.965l-2.898-.777M13.95 4.05l-2.122 2.122m-5.657 5.656l-2.12 2.122" />
                 </svg>
               </div>
               <div className="p-2 text-gray-500 hover:text-gray-300 cursor-not-allowed" title="Magic Wand (Coming Soon)">
                 <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
                 </svg>
               </div>
            </div>

            <CanvasEditor 
              imageMetadata={imageMetadata}
              layers={layers}
              selectedLayerId={selectedLayerId}
              onSelectLayer={setSelectedLayerId}
              onGenerateLayer={handleGenerateLayer}
              onUpdatePrompt={handleUpdatePrompt}
              onShufflePrompt={handleShufflePrompt}
              onDownloadLayer={downloadLayer}
              onLayerMove={handleLayerMove}
              isShuffling={isShuffling}
            />

            <div 
               className={`
                 transition-all duration-300 ease-in-out border-l border-dark-800 bg-dark-900 
                 flex flex-col shrink-0 overflow-hidden relative
                 ${showLayerPanel ? 'w-80 opacity-100' : 'w-0 opacity-0 border-l-0'}
               `}
            >
              <div className="w-80 h-full flex flex-col">
                <LayerList 
                  layers={layers} 
                  selectedLayerId={selectedLayerId}
                  onSelectLayer={setSelectedLayerId}
                  onToggleVisibility={(id) => {
                    setLayers(prev => prev.map(l => 
                      l.id === id ? { ...l, isVisible: !l.isVisible } : l
                    ));
                  }}
                  onDownloadLayer={downloadLayer}
                  onClose={() => setShowLayerPanel(false)}
                  activeTab={activeTab}
                  onTabChange={setActiveTab}
                />
              </div>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

import React, { useEffect, useRef, useState, useLayoutEffect } from 'react';
import { Layer, ImageMetadata, LayerType } from '../types';
import { Button } from './Button';

interface CanvasEditorProps {
  imageMetadata: ImageMetadata;
  layers: Layer[];
  selectedLayerId: string | null;
  onSelectLayer: (id: string | null) => void;
  onGenerateLayer: (layerId: string, prompt: string) => void;
  onUpdatePrompt: (layerId: string, newPrompt: string) => void;
  onShufflePrompt: (layerId: string) => void;
  onDownloadLayer: (layer: Layer) => void;
  onLayerMove: (id: string, x: number, y: number) => void;
  isShuffling?: string | null;
}

export const CanvasEditor: React.FC<CanvasEditorProps> = ({ 
  imageMetadata, 
  layers, 
  selectedLayerId,
  onSelectLayer,
  onGenerateLayer,
  onUpdatePrompt,
  onShufflePrompt,
  onDownloadLayer,
  onLayerMove,
  isShuffling
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });

  // Canvas Panning State
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  // Prompt Box Dragging State
  const [promptBoxOffset, setPromptBoxOffset] = useState({ x: 0, y: 0 });
  const [isDraggingBox, setIsDraggingBox] = useState(false);
  const [boxDragStart, setBoxDragStart] = useState({ x: 0, y: 0 });

  // Layer Dragging State
  const [draggingLayerId, setDraggingLayerId] = useState<string | null>(null);
  const [dragLayerStart, setDragLayerStart] = useState({ x: 0, y: 0 }); // Mouse screen coords
  const [layerInitialPos, setLayerInitialPos] = useState({ x: 0, y: 0 }); // Layer canvas coords

  // Track container dimensions to force re-render on resize
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

  const selectedLayer = layers.find(l => l.id === selectedLayerId);
  const compositionLayer = layers.find(l => l.type === LayerType.COMPOSITION);

  // Reset box position when changing layers
  useEffect(() => {
    setPromptBoxOffset({ x: 0, y: 0 });
  }, [selectedLayerId]);

  // Monitor resize for layout updates
  useLayoutEffect(() => {
    if (!containerRef.current) return;

    const resizeObserver = new ResizeObserver((entries) => {
      for (let entry of entries) {
        setContainerSize({
          width: entry.contentRect.width,
          height: entry.contentRect.height
        });
      }
    });

    resizeObserver.observe(containerRef.current);

    return () => {
      resizeObserver.disconnect();
    };
  }, []);

  // Fit image to screen on load (only once or when image changes)
  useEffect(() => {
    if (containerRef.current) {
       const { clientWidth, clientHeight } = containerRef.current;
       // We show 2 images side by side with gap.
       // The effective width per image is approx (width / 2) - padding
       const panelWidth = clientWidth / 2;

       const scaleX = (panelWidth - 40) / imageMetadata.width;
       const scaleY = (clientHeight - 80) / imageMetadata.height;
       const fitScale = Math.min(scaleX, scaleY, 0.9); // 0.9 to give some breathing room
       setScale(fitScale);
    }
  }, [imageMetadata]);

  const handleWheel = (e: React.WheelEvent) => {
    e.stopPropagation();
    if (e.ctrlKey || e.metaKey) {
       // Zoom
       const newScale = Math.max(0.05, Math.min(8, scale - e.deltaY * 0.001));
       setScale(newScale);
    } else {
       // Pan
       setOffset(prev => ({
          x: prev.x - e.deltaX,
          y: prev.y - e.deltaY
       }));
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
     if (e.button === 1 || e.button === 0) { // Middle or left click
        setIsDragging(true);
        setDragStart({ x: e.clientX - offset.x, y: e.clientY - offset.y });
     }
  };

  const handleLayerMouseDown = (e: React.MouseEvent, layer: Layer) => {
    e.stopPropagation(); // Prevent panning
    e.preventDefault(); // Prevent default drag behavior

    onSelectLayer(layer.id);
    setDraggingLayerId(layer.id);
    setDragLayerStart({ x: e.clientX, y: e.clientY });
    setLayerInitialPos({ x: layer.originalX, y: layer.originalY });
  };

  const handlePromptBoxMouseDown = (e: React.MouseEvent) => {
    // Stop propagation to prevent canvas panning
    e.stopPropagation();
    setIsDraggingBox(true);
    setBoxDragStart({ x: e.clientX - promptBoxOffset.x, y: e.clientY - promptBoxOffset.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (draggingLayerId) {
      e.preventDefault();
      const dx = (e.clientX - dragLayerStart.x) / scale;
      const dy = (e.clientY - dragLayerStart.y) / scale;
      onLayerMove(draggingLayerId, layerInitialPos.x + dx, layerInitialPos.y + dy);
    } else if (isDraggingBox) {
      e.preventDefault();
      setPromptBoxOffset({
        x: e.clientX - boxDragStart.x,
        y: e.clientY - boxDragStart.y
      });
    } else if (isDragging) {
      setOffset({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      });
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    setIsDraggingBox(false);
    setDraggingLayerId(null);
  };

  // Logic for positioning the prompt box & drawing lines
  let promptBoxPos = null;
  let lineCoords = null;
  let rightPanelTopLeft = { x: 0, y: 0 };

  if (containerRef.current && containerSize.width > 0) {
    const { width: clientWidth, height: clientHeight } = containerSize;

    // The Right Panel Center
    const rightPanelCenterX = (clientWidth * 0.75); 
    const panelCenterY = clientHeight / 2;

    // Image centers
    const imgCenterX = imageMetadata.width / 2;
    const imgCenterY = imageMetadata.height / 2;

    // Calculate Top-Left of the image in right panel (for the master handle)
    // ScreenX = CenterX + OffsetX + (LocalX - ImgCenterX) * Scale
    rightPanelTopLeft = {
      x: rightPanelCenterX + offset.x + (0 - imgCenterX) * scale,
      y: panelCenterY + offset.y + (0 - imgCenterY) * scale
    };

    if (selectedLayer) {
      const layerCenterX = selectedLayer.originalX + selectedLayer.width / 2;
      const layerCenterY = selectedLayer.originalY + selectedLayer.height / 2;

      const dx = layerCenterX - imgCenterX;
      const dy = layerCenterY - imgCenterY;

      // Screen Position of the Layer in the Right Panel
      const layerScreenX = rightPanelCenterX + offset.x + (dx * scale);
      const layerScreenY = panelCenterY + offset.y + (dy * scale);

      // Prompt Box Positioning logic
      const boxWidth = 300;
      const boxHeight = 220; 
      const margin = 80 * scale; 

      // Prefer placing box to the right, flip if no space
      let boxX = layerScreenX + margin;
      let boxY = layerScreenY - boxHeight / 2;

      // Boundary checks
      if (boxX + boxWidth > clientWidth - 20) {
         boxX = layerScreenX - margin - boxWidth;
      }
      boxY = Math.max(10, Math.min(clientHeight - boxHeight - 10, boxY));

      // Apply manual drag offset
      boxX += promptBoxOffset.x;
      boxY += promptBoxOffset.y;

      promptBoxPos = { x: boxX, y: boxY };

      // Determine line attachment point
      const attachToLeftOfBox = boxX > layerScreenX;

      lineCoords = {
        x1: layerScreenX,
        y1: layerScreenY,
        x2: attachToLeftOfBox ? boxX : boxX + boxWidth, 
        y2: boxY + 60 // Roughly align with text area
      };
    }
  }

  // Derived transform styles
  const leftPanelCenter = { x: (containerSize.width || 0) * 0.25, y: (containerSize.height || 0) * 0.5 };
  const rightPanelCenter = { x: (containerSize.width || 0) * 0.75, y: (containerSize.height || 0) * 0.5 };

  return (
    <div 
      ref={containerRef}
      className={`flex-1 bg-[#121212] overflow-hidden relative select-none flex ${isDraggingBox || draggingLayerId ? 'cursor-move' : (isDragging ? 'cursor-grabbing' : 'cursor-grab')}`}
      onWheel={handleWheel}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      {/* Background Grid Pattern */}
      <div className="absolute inset-0 opacity-10 pointer-events-none" 
           style={{
             backgroundImage: 'radial-gradient(#333 1px, transparent 1px)',
             backgroundSize: '20px 20px'
           }} 
      />

      {/* Split Divider */}
      <div className="absolute top-0 bottom-0 w-px bg-dark-700 left-1/2 z-0"></div>

      {/* Labels */}
      <div className="absolute top-4 left-4 z-10 bg-black/50 px-3 py-1 rounded-full border border-white/10 text-xs font-medium text-gray-400">
         Original Source
      </div>
      <div className="absolute top-4 left-[calc(50%+1rem)] z-10 bg-brand-900/50 px-3 py-1 rounded-full border border-brand-500/30 text-xs font-medium text-brand-300">
         Decomposed Layers
      </div>

      {/* SVG Overlay for Connectors (Global) */}
      <svg className="absolute inset-0 pointer-events-none z-40 w-full h-full">
