import { GoogleGenAI, Type } from "@google/genai";
import { DetectedElement, LayerType } from "../types";

// Schema for the Gemini response
const segmentationSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      label: {
        type: Type.STRING,
        description: "A short descriptive name for the object or layer (e.g., 'Red Car', 'Header Text', 'Background').",
      },
      category: {
        type: Type.STRING,
        enum: [LayerType.OBJECT, LayerType.TEXT, LayerType.BACKGROUND, LayerType.COMPOSITION],
        description: "The type of layer. Use 'composition' for the entry describing the entire image style.",
      },
      box_2d: {
        type: Type.ARRAY,
        items: { type: Type.INTEGER },
        description: "Bounding box in the format [ymin, xmin, ymax, xmax] on a 0-1000 scale.",
      },
      visual_prompt: {
        type: Type.STRING,
        description: "A structured prompt. For 'composition', use headers: Theme, Headline & Text, Visuals, Layout/Sections, Footer, Style. For objects, use: Object, Visual Details, Style.",
      }
    },
    required: ["label", "category", "box_2d", "visual_prompt"],
  },
};

export const analyzeImageStructure = async (
  base64Image: string,
  mimeType: string
): Promise<DetectedElement[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      Analyze this image for a design decomposition tool. 
      Identify distinct visual elements that a designer would want on separate layers.

      Rules:
      1. Always identify the main "Background" or scene setting.
      2. Identify primary foreground objects (people, products, vehicles).
      3. Identify distinct text blocks (headlines, body copy).
      4. INCLUDE a "composition" element that covers the entire image ([0, 0, 1000, 1000]).
      5. Be precise with bounding boxes (0-1000 scale).
      6. Do not overlap boxes excessively unless objects are truly nested.

      CRITICAL - PROMPT STRUCTURE:
      7. For the 'composition' element, the 'visual_prompt' MUST follow this exact structure:
         Create a [Type of Design, e.g. Flyer, Poster].
         Theme: [Description of mood/theme].
         Headline & Text: [Details of main titles, subtext, taglines, font styles].
         Visuals: [Detailed description of models, objects, props, effects, lighting].
         Layout/Sections: [Description of specific sections like Services, lists].
         Footer: [Details of footer area, contact info].
         Style: [Art style, colors, resolution, finishing].

      8. For individual elements (objects/layers), use a similar structured format focused on that object:
         Object: [Name/Type]
         Visuals: [Detailed texture, lighting, angle, material, colors]
         Style: [Matches the main composition style]

      9. Return a list of these elements in JSON format.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: prompt,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: segmentationSchema,
        temperature: 0.2,
      },
    });

    let text = response.text;
    if (!text) {
      throw new Error("No response from AI");
    }

    // Clean markdown if present
    if (text.trim().startsWith("```")) {
      text = text.replace(/^```(json)?\s*/, "").replace(/\s*```$/, "");
    }

    const data = JSON.parse(text) as DetectedElement[];
    return data;
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

export const generateElementImage = async (prompt: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: prompt,
          },
        ],
      },
    });

    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image data found in response");
  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

export const regeneratePrompt = async (currentPrompt: string, layerType: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `You are a creative design assistant. Given the following visual prompt for an image layer of type '${layerType}', generate a NEW, CREATIVE variation that maintains the same core concept but uses different adjectives, styles, lighting, or artistic details. Keep it concise.

Current Prompt: ${currentPrompt}

New Variation:`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text?.trim() || currentPrompt;
  } catch (error) {
    console.error("Gemini Regenerate Prompt Error:", error);
    return currentPrompt;
  }
};

export const mergeLayerPrompts = async (prompts: string[]): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Combine the following separate visual descriptions of individual image layers into a single, cohesive, and concise "Compound Prompt" that describes all elements as a single unified visual scene or object.

Layers to Merge:
${prompts.map((p, i) => `${i + 1}. ${p}`).join('\n')}

Unified Compound Prompt:`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text?.trim() || prompts.join(". ");
  } catch (error) {
    console.error("Gemini Merge Prompt Error:", error);
    return prompts.join(". ");
  }
};

