const cropImage = async (
  sourceImage: HTMLImageElement, 
  box_1000: number[]
): Promise<{ url: string; x: number; y: number; w: number; h: number }> => {
  const [ymin, xmin, ymax, xmax] = box_1000;
  const canvas = document.createElement('canvas');
  const x = (xmin / 1000) * sourceImage.naturalWidth;
  const y = (ymin / 1000) * sourceImage.naturalHeight;
  const w = ((xmax - xmin) / 1000) * sourceImage.naturalWidth;
  const h = ((ymax - ymin) / 1000) * sourceImage.naturalHeight;

  if (w <= 0 || h <= 0) {
    canvas.width = 1;
    canvas.height = 1;
    return { url: canvas.toDataURL('image/png'), x, y, w: 0, h: 0 };
  }

  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error("No context");
  ctx.drawImage(sourceImage, x, y, w, h, 0, 0, w, h);
  return { url: canvas.toDataURL('image/png'), x, y, w, h };
};

export default function App() {
  const [state, setState] = useState<AppState>(AppState.LANDING);
  const [imageMetadata, setImageMetadata] = useState<ImageMetadata | null>(null);
  const [layers, setLayers] = useState<Layer[]>([]);
  const [selectedLayerIds, setSelectedLayerIds] = useState<string[]>([]);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isZipping, setIsZipping] = useState(false);
  const [showLayerPanel, setShowLayerPanel] = useState(true);
  const [activeTab, setActiveTab] = useState<'layers' | 'generated'>('layers');
  const [isShuffling, setIsShuffling] = useState<string | null>(null);
  const [isMerging, setIsMerging] = useState(false);

  const downloadLayer = (layer: Layer) => {
    const link = document.createElement('a');
    link.href = layer.imageSrc;
    link.download = `${layer.name.replace(/\s+/g, '_')}_${layer.isGenerated ? 'generated' : 'layer'}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleUpdatePrompt = (layerId: string, newPrompt: string) => {
    setLayers(prev => prev.map(l => l.id === layerId ? { ...l, visual_prompt: newPrompt } : l));
  };

  const handleSelectLayer = (id: string | null, multi: boolean = false) => {
    if (id === null) {
      setSelectedLayerIds([]);
      return;
    }
    if (multi) {
      setSelectedLayerIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
    } else {
      setSelectedLayerIds([id]);
    }
  };

  const handleShufflePrompt = async (layerId: string) => {
    const layer = layers.find(l => l.id === layerId);
    if (!layer || !layer.visual_prompt) return;
    setIsShuffling(layerId);
    try {
      const newPrompt = await regeneratePrompt(layer.visual_prompt, layer.type);
      handleUpdatePrompt(layerId, newPrompt);
    } catch (err) {
      console.error(err);
    } finally {
      setIsShuffling(null);
    }
  };

  const handleMergeAndGenerate = async () => {
    if (selectedLayerIds.length < 2) return;
    const selectedLayers = layers.filter(l => selectedLayerIds.includes(l.id));

    setIsMerging(true);
    try {
      // 1. Calculate Compound Bounding Box
      const boxes = selectedLayers.map(l => l.box);
      const ymin = Math.min(...boxes.map(b => b.ymin));
      const xmin = Math.min(...boxes.map(b => b.xmin));
      const ymax = Math.max(...boxes.map(b => b.ymax));
      const xmax = Math.max(...boxes.map(b => b.xmax));

      // 2. Generate Compound Prompt
      const prompts = selectedLayers.map(l => l.visual_prompt || l.name);
      const compoundPrompt = await mergeLayerPrompts(prompts);

      // 3. Generate Image
      const newImageSrc = await generateElementImage(compoundPrompt);

      // 4. Create New Layer
      const newLayerId = `merge-${Date.now()}`;
      const firstLayer = selectedLayers[0];

      const newLayer: Layer = {
        id: newLayerId,
        name: `Group: ${selectedLayers.map(l => l.name).join(', ').substring(0, 20)}...`,
        type: LayerType.GENERATED,
        isVisible: true,
        box: { ymin, xmin, ymax, xmax },
        imageSrc: newImageSrc,
        originalX: Math.min(...selectedLayers.map(l => l.originalX)),
        originalY: Math.min(...selectedLayers.map(l => l.originalY)),
        width: Math.max(...selectedLayers.map(l => l.originalX + l.width)) - Math.min(...selectedLayers.map(l => l.originalX)),
        height: Math.max(...selectedLayers.map(l => l.originalY + l.height)) - Math.min(...selectedLayers.map(l => l.originalY)),
        visual_prompt: compoundPrompt,
        isGenerated: true,
      };

      setLayers(prev => [...prev, newLayer]);
      setActiveTab('generated');
      setSelectedLayerIds([newLayerId]);
    } catch (err) {
      console.error("Merge error:", err);
      alert("Failed to merge and generate.");
    } finally {
      setIsMerging(false);
    }
  };

  const handleLayerMove = (id: string, x: number, y: number) => {
    setLayers(prev => prev.map(l => l.id === id ? { ...l, originalX: x, originalY: y } : l));
  };

  const handleExportZip = async () => {
    const visibleLayers = layers.filter(l => l.isVisible && l.type !== LayerType.COMPOSITION);
    if (visibleLayers.length === 0) return;
    setIsZipping(true);
    try {
      const zip = new JSZip();
      visibleLayers.forEach((layer, index) => {
        const base64Data = layer.imageSrc.split(',')[1];
        const prefix = layer.isGenerated ? 'generated_' : '';
        const safeName = layer.name.replace(/[^a-z0-9]/gi, '_').toLowerCase() || `layer_${index}`;
        zip.file(`${prefix}${safeName}_${index}.png`, base64Data, { base64: true });
      });
      const blob = await zip.generateAsync({ type: 'blob' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = 'unflatten_layers.zip';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (e) {
      console.error(e);
    } finally {
      setIsZipping(false);
    }
  };

  const handleGenerateLayer = async (layerId: string, prompt: string) => {
    setLayers(prev => prev.map(l => l.id === layerId ? { ...l, isGenerating: true } : l));
    try {
      const newImageSrc = await generateElementImage(prompt);
      const sourceLayer = layers.find(l => l.id === layerId);
      if (!sourceLayer) throw new Error("Source layer not found");
      const newLayerId = `gen-${layerId.substring(0, 8)}-${Date.now()}`;
      const newLayer: Layer = {
        ...sourceLayer,
        id: newLayerId,
        name: `Generated ${sourceLayer.name}`,
        type: LayerType.GENERATED,
        imageSrc: newImageSrc,
        isVisible: true,
        isGenerating: false,
        isGenerated: true,
        parentId: layerId,
        visual_prompt: prompt 
      };
      setLayers(prev => {
        const updated = prev.map(l => l.id === layerId ? { ...l, isGenerating: false } : l);
        return [...updated, newLayer];
      });
      setActiveTab('generated');
      setSelectedLayerIds([newLayerId]);
    } catch (err) {
      console.error(err);
      setLayers(prev => prev.map(l => l.id === layerId ? { ...l, isGenerating: false } : l));
    }
  };

  const handleFileSelect = async (file: File) => {
    setState(AppState.ANALYZING);
    setErrorMsg(null);
    setLayers([]);
    setActiveTab('layers');
    const reader = new FileReader();
    reader.onload = async (e) => {
      const src = e.target?.result as string;
      const img = new Image();
      img.onload = async () => {
        setImageMetadata({ width: img.naturalWidth, height: img.naturalHeight, src, file });
        const base64Data = src.split(',')[1];
        try {
          const detectedElements = await analyzeImageStructure(base64Data, file.type);
          const processedLayers: Layer[] = [];
          let hasComposition = false;
          for (let i = 0; i < detectedElements.length; i++) {
            const element = detectedElements[i];
            const cropped = await cropImage(img, element.box_2d);
            if (cropped.w <= 0 || cropped.h <= 0) continue;
            if (element.category === LayerType.COMPOSITION) hasComposition = true;
            processedLayers.push({
              id: `layer-${i}-${Date.now()}`,
              name: element.label,
              type: element.category,
              isVisible: element.category !== LayerType.COMPOSITION,
              box: { ymin: element.box_2d[0], xmin: element.box_2d[1], ymax: element.box_2d[2], xmax: element.box_2d[3] },
              imageSrc: cropped.url,
              originalX: cropped.x,
              originalY: cropped.y,
              width: cropped.w,
              height: cropped.h,
              visual_prompt: element.visual_prompt || `A high quality image of ${element.label}`
            });
          }
          if (!hasComposition) {
            processedLayers.unshift({
              id: `layer-comp-${Date.now()}`,
              name: "Full Composition",
              type: LayerType.COMPOSITION,
              isVisible: false,
              box: { ymin: 0, xmin: 0, ymax: 1000, xmax: 1000 },
              imageSrc: src,
              originalX: 0,
              originalY: 0,
              width: img.naturalWidth,
              height: img.naturalHeight,
              visual_prompt: "A detailed composition description."
            });
          }
          setLayers(processedLayers);
          setState(AppState.EDITING);
        } catch (err: any) {
          setErrorMsg(err.message || "Failed to analyze image.");
          setState(AppState.ERROR);
        }
      };
      img.src = src;
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="h-screen w-screen bg-dark-950 flex flex-col font-sans text-gray-100 overflow-hidden">
      <header className="h-14 border-b border-dark-800 bg-dark-900 flex items-center justify-between px-4 z-10 shrink-0">
        <div className="flex items-center space-x-2 cursor-pointer" onClick={() => setState(AppState.LANDING)}>
          <div className="w-6 h-6 bg-gradient-to-br from-brand-500 to-indigo-600 rounded flex items-center justify-center">
            <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
          </div>
          <span className="font-bold text-lg tracking-tight">Unflatten<span className="text-brand-500">AI</span></span>
        </div>
        {state === AppState.EDITING && (
          <div className="flex items-center space-x-2">
            <Button variant="ghost" size="sm" onClick={() => setState(AppState.LANDING)}>New</Button>
            <Button variant="secondary" size="sm" onClick={() => setShowLayerPanel(!showLayerPanel)} className={showLayerPanel ? 'bg-dark-700' : ''}>
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </Button>
            <div className="w-px h-6 bg-dark-800 mx-2"></div>
            <Button variant="primary" size="sm" disabled={isZipping} onClick={handleExportZip}>
              {isZipping ? "Zipping..." : "Download ZIP"}
            </Button>
          </div>
        )}
      </header>
      <main className="flex-1 relative flex overflow-hidden">
        {state === AppState.LANDING && <LandingPage onFileSelect={handleFileSelect} />}
        {state === AppState.ANALYZING && (
          <div className="w-full h-full flex flex-col items-center justify-center space-y-6 bg-dark-900">
             <div className="relative w-24 h-24">
               <div className="absolute inset-0 border-4 border-dark-700 rounded-full"></div>
               <div className="absolute inset-0 border-4 border-brand-500 rounded-full border-t-transparent animate-spin"></div>
             </div>
             <h3 className="text-xl font-medium text-white mb-2">Deconstructing Image...</h3>
          </div>
        )}
        {state === AppState.EDITING && imageMetadata && (
          <>
            <CanvasEditor 
              imageMetadata={imageMetadata}
              layers={layers}
              selectedLayerIds={selectedLayerIds}
              onSelectLayer={handleSelectLayer}
              onGenerateLayer={handleGenerateLayer}
              onUpdatePrompt={handleUpdatePrompt}
              onShufflePrompt={handleShufflePrompt}
              onDownloadLayer={downloadLayer}
              onLayerMove={handleLayerMove}
              isShuffling={isShuffling}
            />
            <div className={`transition-all duration-300 ease-in-out border-l border-dark-800 bg-dark-900 flex flex-col shrink-0 overflow-hidden relative ${showLayerPanel ? 'w-80 opacity-100' : 'w-0 opacity-0 border-l-0'}`}>
              <div className="w-80 h-full flex flex-col">
                <LayerList 
                  layers={layers} 
                  selectedLayerIds={selectedLayerIds}
                  onSelectLayer={handleSelectLayer}
                  onToggleVisibility={(id) => setLayers(prev => prev.map(l => l.id === id ? { ...l, isVisible: !l.isVisible } : l))}
                  onDownloadLayer={downloadLayer}
                  onClose={() => setShowLayerPanel(false)}
                  activeTab={activeTab}
                  onTabChange={setActiveTab}
                  onMergeAndGenerate={handleMergeAndGenerate}
                  isMerging={isMerging}
                />
              </div>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

import React from 'react';
import { Layer, LayerType } from '../types';
import { Button } from './Button';

interface LayerListProps {
  layers: Layer[];
  selectedLayerIds: string[];
  onSelectLayer: (id: string, multi: boolean) => void;
  onToggleVisibility: (id: string) => void;
  onDownloadLayer: (layer: Layer) => void;
  onClose?: () => void;
  activeTab: 'layers' | 'generated';
  onTabChange: (tab: 'layers' | 'generated') => void;
  onMergeAndGenerate: () => void;
  isMerging: boolean;
}

const LayerIcon = ({ type }: { type: LayerType }) => {
  switch (type) {
    case LayerType.BACKGROUND:
      return (
        <svg className="w-4 h-4 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
        </svg>
      );
    case LayerType.TEXT:
      return (
        <svg className="w-4 h-4 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
        </svg>
      );
    case LayerType.GENERATED:
      return (
        <svg className="w-4 h-4 text-brand-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
        </svg>
      );
    default:
      return (
        <svg className="w-4 h-4 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
        </svg>
      );
  }
};

export const LayerList: React.FC<LayerListProps> = ({ 
  layers, 
  selectedLayerIds, 
  onSelectLayer, 
  onToggleVisibility,
  onDownloadLayer,
  onClose,
  activeTab,
  onTabChange,
  onMergeAndGenerate,
  isMerging
}) => {
  const displayedLayers = layers.filter(l => {
    if (activeTab === 'generated') {
      return l.type === LayerType.GENERATED;
    } else {
      return l.type !== LayerType.GENERATED && l.type !== LayerType.COMPOSITION;
    }
  });

  const compositionLayer = layers.find(l => l.type === LayerType.COMPOSITION);

  return (
    <div className="flex flex-col h-full bg-dark-900 w-full">
      <div className="p-4 border-b border-dark-800 flex justify-between items-center">
        <h2 className="text-sm font-semibold text-gray-200">Inspector</h2>
        {onClose && (
          <button onClick={onClose} className="text-gray-500 hover:text-white"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
        )}
      </div>

      <div className="flex border-b border-dark-800">
        <button className={`flex-1 py-3 text-xs font-medium text-center ${activeTab === 'layers' ? 'text-brand-400 border-b-2 border-brand-500' : 'text-gray-500'}`} onClick={() => onTabChange('layers')}>Layers</button>
        <button className={`flex-1 py-3 text-xs font-medium text-center ${activeTab === 'generated' ? 'text-brand-400 border-b-2 border-brand-500' : 'text-gray-500'}`} onClick={() => onTabChange('generated')}>Generated</button>
      </div>

      {activeTab === 'layers' && (
        <div className="p-2 border-b border-dark-800 space-y-2">
           {compositionLayer && (
             <button onClick={() => onSelectLayer(compositionLayer.id, false)} className={`w-full py-2 px-3 rounded flex items-center justify-center space-x-2 transition-all ${selectedLayerIds.includes(compositionLayer.id) ? 'bg-brand-600 text-white shadow-lg' : 'bg-brand-900/20 border border-brand-500/20 text-brand-300'}`}>
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg>
                <span className="text-xs font-medium">Full Remix</span>
             </button>
           )}
           {selectedLayerIds.length >= 2 && (
             <Button variant="primary" size="sm" className="w-full bg-indigo-600 hover:bg-indigo-500 text-xs" onClick={onMergeAndGenerate} disabled={isMerging}>
                {isMerging ? "Merging..." : `Group & Generate (${selectedLayerIds.length})`}
             </Button>
           )}
        </div>
      )}

      <div className="flex-1 overflow-y-auto p-2 space-y-1">
        {displayedLayers.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-40 text-gray-600 text-center p-4">
             <p className="text-xs">No layers found.</p>
          </div>
        ) : (
          displayedLayers.map((layer) => {
            const isSelected = selectedLayerIds.includes(layer.id);
            return (
              <div 
                key={layer.id}
                onClick={(e) => onSelectLayer(layer.id, e.shiftKey || e.metaKey || e.ctrlKey)}
                className={`group flex items-center p-2 rounded-md cursor-pointer border ${isSelected ? 'bg-brand-900/30 border-brand-500/30' : 'hover:bg-dark-800 border-transparent'}`}
              >
                <button onClick={(e) => { e.stopPropagation(); onToggleVisibility(layer.id); }} className="p-1 rounded text-gray-400 mr-2">
                  {layer.isVisible ? <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg> : <svg className="w-4 h-4 text-gray-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21" /></svg>}
                </button>
                <div className="w-10 h-10 bg-dark-800 rounded border border-dark-700 mr-3 overflow-hidden checkerboard shrink-0 relative">
                  {isSelected && <div className="absolute inset-0 bg-brand-500/20 flex items-center justify-center"><svg className="w-4 h-4 text-brand-400" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" /></svg></div>}
                  <img src={layer.imageSrc} className="w-full h-full object-contain" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className={`text-sm truncate ${isSelected ? 'text-brand-100 font-medium' : 'text-gray-300'}`}>{layer.name}</p>
                  <div className="flex items-center space-x-1"><LayerIcon type={layer.type} /><span className="text-xs text-gray-500 capitalize">{layer.type}</span></div>
                </div>
              </div>
            );
          })
        )}
      </div>
      <div className="p-4 border-t border-dark-800"><Button variant="secondary" className="w-full text-xs" disabled>Export PSD (Pro)</Button></div>
    </div>
  );
};

import React, { useEffect, useRef, useState, useLayoutEffect } from 'react';
import { Layer, ImageMetadata, LayerType } from '../types';
import { Button } from './Button';

interface CanvasEditorProps {
  imageMetadata: ImageMetadata;
  layers: Layer[];
  selectedLayerIds: string[];
  onSelectLayer: (id: string | null, multi: boolean) => void;
  onGenerateLayer: (layerId: string, prompt: string) => void;
  onUpdatePrompt: (layerId: string, newPrompt: string) => void;
  onShufflePrompt: (layerId: string) => void;
  onDownloadLayer: (layer: Layer) => void;
  onLayerMove: (id: string, x: number, y: number) => void;
  isShuffling?: string | null;
}

export const CanvasEditor: React.FC<CanvasEditorProps> = ({ 
  imageMetadata, 
  layers, 
  selectedLayerIds,
  onSelectLayer,
  onGenerateLayer,
  onUpdatePrompt,
  onShufflePrompt,
  onDownloadLayer,
  onLayerMove,
  isShuffling
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [promptBoxOffset, setPromptBoxOffset] = useState({ x: 0, y: 0 });
  const [isDraggingBox, setIsDraggingBox] = useState(false);
  const [boxDragStart, setBoxDragStart] = useState({ x: 0, y: 0 });
  const [draggingLayerId, setDraggingLayerId] = useState<string | null>(null);
  const [dragLayerStart, setDragLayerStart] = useState({ x: 0, y: 0 });
  const [layerInitialPos, setLayerInitialPos] = useState({ x: 0, y: 0 });
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

  const selectedLayers = layers.filter(l => selectedLayerIds.includes(l.id));
  const compositionLayer = layers.find(l => l.type === LayerType.COMPOSITION);

  useEffect(() => { setPromptBoxOffset({ x: 0, y: 0 }); }, [selectedLayerIds]);

  useLayoutEffect(() => {
    if (!containerRef.current) return;
    const observer = new ResizeObserver((entries) => {
      for (let entry of entries) setContainerSize({ width: entry.contentRect.width, height: entry.contentRect.height });
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (containerRef.current) {
       const { clientWidth, clientHeight } = containerRef.current;
       const fitScale = Math.min((clientWidth / 2 - 40) / imageMetadata.width, (clientHeight - 80) / imageMetadata.height, 0.9);
       setScale(fitScale);
    }
  }, [imageMetadata]);

  const handleLayerMouseDown = (e: React.MouseEvent, layer: Layer) => {
    e.stopPropagation(); e.preventDefault();
    onSelectLayer(layer.id, e.shiftKey || e.metaKey || e.ctrlKey);
    setDraggingLayerId(layer.id);
    setDragLayerStart({ x: e.clientX, y: e.clientY });
    setLayerInitialPos({ x: layer.originalX, y: layer.originalY });
  };

  let promptBoxPos = null;
  let lineCoords: { x1: number, y1: number, x2: number, y2: number }[] = [];
  let rightPanelTopLeft = { x: 0, y: 0 };

  if (containerRef.current && containerSize.width > 0) {
    const { width: clientWidth, height: clientHeight } = containerSize;
    const rightPanelCenterX = clientWidth * 0.75; 
    const panelCenterY = clientHeight / 2;
    const imgCenterX = imageMetadata.width / 2;
    const imgCenterY = imageMetadata.height / 2;

    rightPanelTopLeft = {
      x: rightPanelCenterX + offset.x + (0 - imgCenterX) * scale,
      y: panelCenterY + offset.y + (0 - imgCenterY) * scale
    };

    if (selectedLayers.length > 0) {
      // Calculate geometric center of selected group
      const avgX = selectedLayers.reduce((acc, l) => acc + l.originalX + l.width/2, 0) / selectedLayers.length;
      const avgY = selectedLayers.reduce((acc, l) => acc + l.originalY + l.height/2, 0) / selectedLayers.length;

      const layerScreenX = rightPanelCenterX + offset.x + (avgX - imgCenterX) * scale;
      const layerScreenY = panelCenterY + offset.y + (avgY - imgCenterY) * scale;

      const boxWidth = 300, boxHeight = 220; 
      let boxX = layerScreenX + 80 * scale, boxY = layerScreenY - boxHeight / 2;

      if (boxX + boxWidth > clientWidth - 20) boxX = layerScreenX - 80 * scale - boxWidth;
      boxY = Math.max(10, Math.min(clientHeight - boxHeight - 10, boxY));
      boxX += promptBoxOffset.x; boxY += promptBoxOffset.y;

      promptBoxPos = { x: boxX, y: boxY };
      const attachX = boxX > layerScreenX ? boxX : boxX + boxWidth;

      selectedLayers.forEach(l => {
        const lx = rightPanelCenterX + offset.x + (l.originalX + l.width/2 - imgCenterX) * scale;
        const ly = panelCenterY + offset.y + (l.originalY + l.height/2 - imgCenterY) * scale;
        lineCoords.push({ x1: lx, y1: ly, x2: attachX, y2: boxY + 60 });
      });
    }
  }

  return (
    <div 
      ref={containerRef}
      className={`flex-1 bg-[#121212] overflow-hidden relative flex ${isDraggingBox || draggingLayerId ? 'cursor-move' : (isDragging ? 'cursor-grabbing' : 'cursor-grab')}`}
      onWheel={(e) => {
        if (e.ctrlKey) setScale(s => Math.max(0.05, Math.min(8, s - e.deltaY * 0.001)));
        else setOffset(prev => ({ x: prev.x - e.deltaX, y: prev.y - e.deltaY }));
      }}
      onMouseDown={(e) => { setIsDragging(true); setDragStart({ x: e.clientX - offset.x, y: e.clientY - offset.y }); }}
      onMouseMove={(e) => {
        if (draggingLayerId) onLayerMove(draggingLayerId, layerInitialPos.x + (e.clientX - dragLayerStart.x) / scale, layerInitialPos.y + (e.clientY - dragLayerStart.y) / scale);
        else if (isDraggingBox) setPromptBoxOffset({ x: e.clientX - boxDragStart.x, y: e.clientY - boxDragStart.y });
        else if (isDragging) setOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
      }}
      onMouseUp={() => { setIsDragging(false); setIsDraggingBox(false); setDraggingLayerId(null); }}
    >
      <div className="absolute inset-0 opacity-10 pointer-events-none" style={{ backgroundImage: 'radial-gradient(#333 1px, transparent 1px)', backgroundSize: '20px 20px' }} />
      <div className="absolute top-0 bottom-0 w-px bg-dark-700 left-1/2 z-0"></div>

      <svg className="absolute inset-0 pointer-events-none z-40 w-full h-full">
         <defs>
           <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="10" refY="3.5" orient="auto"><polygon points="0 0, 10 3.5, 0 7" fill="#0ea5e9" /></marker>
           <filter id="glow"><feGaussianBlur stdDeviation="2" result="coloredBlur"/><feMerge><feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
         </defs>
         {lineCoords.map((lc, i) => (
           <path key={i} d={`M${lc.x1},${lc.y1} C${(lc.x1 + lc.x2)/2},${lc.y1} ${(lc.x1 + lc.x2)/2},${lc.y2} ${lc.x2},${lc.y2}`} stroke="#0ea5e9" strokeWidth="1" fill="none" filter="url(#glow)" className="opacity-40" />
         ))}
      </svg>

      {/* Panels */}
      {[0.25, 0.75].map((centerXMult, i) => (
        <div key={i} className="absolute w-0 h-0 flex items-center justify-center" style={{ left: (containerSize.width || 0) * centerXMult, top: (containerSize.height || 0) * 0.5 }}>
          <div style={{ transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})`, width: imageMetadata.width, height: imageMetadata.height, position: 'absolute', left: -imageMetadata.width / 2, top: -imageMetadata.height / 2 }}>
            <img src={imageMetadata.src} className={`w-full h-full object-contain ${i === 0 ? 'opacity-80' : 'opacity-0'}`} draggable={false} />
            {i === 1 && layers.map(layer => layer.isVisible && layer.type !== LayerType.COMPOSITION && (
              <div key={layer.id} className="absolute group" style={{ left: layer.originalX, top: layer.originalY, width: layer.width, height: layer.height, zIndex: selectedLayerIds.includes(layer.id) ? 50 : 10, cursor: 'move' }} onMouseDown={(e) => handleLayerMouseDown(e, layer)}>
                <div className={`absolute -inset-1 rounded-sm border-2 pointer-events-none ${selectedLayerIds.includes(layer.id) ? 'border-brand-500 bg-brand-500/10' : 'border-transparent group-hover:border-brand-500/30'}`} />
                <img src={layer.imageSrc} className={`w-full h-full object-contain pointer-events-none ${layer.isGenerating ? 'opacity-50 animate-pulse' : ''}`} draggable={false} />
              </div>
            ))}
          </div>
        </div>
      ))}

      {compositionLayer && (
        <div className="absolute z-50 transform -translate-x-1/2 -translate-y-1/2" style={{ left: rightPanelTopLeft.x, top: rightPanelTopLeft.y }} onClick={(e) => { e.stopPropagation(); onSelectLayer(compositionLayer.id, e.shiftKey); }}>
           <div className={`w-10 h-10 rounded-full flex items-center justify-center shadow-lg border transition-all ${selectedLayerIds.includes(compositionLayer.id) ? 'bg-brand-500 text-white' : 'bg-dark-800 text-brand-400'}`}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg></div>
        </div>
      )}

      {selectedLayers.length === 1 && promptBoxPos && (
        <div className="absolute z-50 w-72 bg-black/60 backdrop-blur-xl border border-white/10 rounded-xl flex flex-col shadow-2xl" style={{ left: promptBoxPos.x, top: promptBoxPos.y }}>
          <div className="p-3 border-b border-white/10 flex justify-between items-center bg-white/5 rounded-t-xl cursor-move" onMouseDown={(e) => { e.stopPropagation(); setIsDraggingBox(true); setBoxDragStart({ x: e.clientX - promptBoxOffset.x, y: e.clientY - promptBoxOffset.y }); }}>
             <span className="text-[10px] font-bold text-gray-200 uppercase">{selectedLayers[0].name}</span>
          </div>
          <div className="p-3 space-y-3">
             <div className="relative">
               <textarea className="w-full bg-black/20 text-gray-200 text-xs p-3 pr-10 rounded-lg border border-white/10 focus:border-brand-500 outline-none resize-none min-h-[80px]" value={selectedLayers[0].visual_prompt || ''} onChange={(e) => onUpdatePrompt(selectedLayers[0].id, e.target.value)} />
               <button className="absolute top-2 right-2 p-1.5 text-gray-400 hover:text-white" onClick={() => onShufflePrompt(selectedLayers[0].id)} disabled={!!isShuffling}><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg></button>
             </div>
             <Button variant="primary" size="sm" className="w-full text-[11px]" onClick={() => onGenerateLayer(selectedLayers[0].id, selectedLayers[0].visual_prompt || selectedLayers[0].name)} disabled={selectedLayers[0].isGenerating}>Generate</Button>
          </div>
        </div>
      )}
    </div>
  );
};
